import { LogUtil } from "../../utils/LogUtil.mjs";

const GROUP_TYPE_PATTERN = /^(group|party|crew|team|squad|troupe|company|band|posse)s?$/i;
const MEMBER_KEY_PATTERN = /(member|party|crew|roster|character|actor)/i;
const PLAIN_MEMBER_KEY_PATTERN = /(member|roster)/i;

/**
 * @typedef {Object} MemberPath
 * @property {string} path - Path inside actor.system holding the member list
 * @property {string|null} key - Key of the actor reference inside each entry, null when entries are references
 * @property {"id"|"uuid"|null} ref - How the reference is stored, null when only known from probing data
 */

/**
 * Finds actor types that hold other actors as members, so the Groups tab can offer a system's own group
 * actors even when no adapter declares them.
 * Types with a data model are detected by schema: a list field whose entries are Actor references.
 * Types without one fall back to a group-like type name; their members are found by probing the actor's data.
 * @module adapters/generic/GenericGroups
 */
export class GenericGroups {
  /** @type {Map<string, MemberPath[]>|null} */
  static #schemaTypes = null;

  /**
   * Actor types detected as holding members: by schema, or by a group-like name for types without a data model,
   * whether or not any actor of the type exists yet
   * @returns {string[]}
   */
  static detectedTypes() {
    const types = new Set(this.#getSchemaTypes().keys());
    for (const type of this.actorTypes()) {
      if (types.has(type) || CONFIG.Actor?.dataModels?.[type]) continue;
      if (this.#isNamedGroupType(type)) types.add(type);
    }
    return Array.from(types);
  }

  /**
   * Whether the actor's type holds members
   * @param {Actor} actor
   * @returns {boolean}
   */
  static isGroupActor(actor) {
    if (!actor?.type) return false;
    if (this.#getSchemaTypes().has(actor.type)) return true;
    return !CONFIG.Actor?.dataModels?.[actor.type] && this.#isNamedGroupType(actor.type);
  }

  /**
   * Members of a group actor, resolved from every member list its type declares
   * @param {Actor} groupActor
   * @returns {Promise<Array<{actor: Actor, quantity: number}>>}
   */
  static async getGroupMembers(groupActor) {
    const paths = this.#getSchemaTypes().get(groupActor?.type) ?? this.#probePaths(groupActor);
    const members = [];
    const seen = new Set();
    for (const { path, key } of paths) {
      for (const entry of this.#entries(groupActor, path)) {
        const ref = key ? entry?.[key] : entry;
        const actor = await this.#resolveActor(ref);
        if (!actor || seen.has(actor.id)) continue;
        seen.add(actor.id);
        members.push({ actor, quantity: Number(entry?.quantity?.value ?? entry?.quantity ?? 1) || 1 });
      }
    }
    return members;
  }

  /**
   * Remove an actor from a group actor's member lists. Uses the group's own removal method when the system
   * provides one (`system.removeMember(actor)` as in D&D 5e, `removeMembers(...uuids)` as in PF2e), otherwise
   * rewrites the stored member lists without the actor.
   * @param {Actor} groupActor
   * @param {Actor} memberActor - World actor to remove
   * @returns {Promise<boolean>} Whether anything was removed
   */
  static async removeMember(groupActor, memberActor) {
    if (!groupActor || !memberActor) return false;
    if (typeof groupActor.system?.removeMember === "function") {
      await groupActor.system.removeMember(memberActor);
      return true;
    }
    if (typeof groupActor.removeMembers === "function") {
      await groupActor.removeMembers(memberActor.uuid);
      return true;
    }
    const paths = this.#getSchemaTypes().get(groupActor.type) ?? this.#probePaths(groupActor);
    const update = {};
    for (const { path, key } of paths) {
      const stored = foundry.utils.getProperty(groupActor._source?.system ?? {}, path);
      const entries = Array.isArray(stored) ? stored : stored instanceof Set ? Array.from(stored) : null;
      if (!entries) continue;
      const kept = entries.filter(entry => !this.#refersTo(key ? entry?.[key] : entry, memberActor));
      if (kept.length !== entries.length) update[`system.${path}`] = kept;
    }
    if (Object.keys(update).length === 0) return false;
    await groupActor.update(update);
    return true;
  }

  /**
   * Whether a stored member reference points at the actor: its id, its uuid, or an object carrying either
   * @param {*} ref
   * @param {Actor} actor
   * @returns {boolean}
   */
  static #refersTo(ref, actor) {
    if (!ref) return false;
    if (ref instanceof Actor) return ref.id === actor.id;
    if (typeof ref === "object") return this.#refersTo(ref.uuid ?? ref.id ?? ref._id, actor);
    const value = String(ref);
    return value === actor.id || value === actor.uuid || value.endsWith(`.${actor.id}`);
  }

  /**
   * Actor types with a data model whose schema contains an Actor reference list, cached after first use
   * @returns {Map<string, MemberPath[]>}
   */
  static #getSchemaTypes() {
    if (this.#schemaTypes) return this.#schemaTypes;
    const types = new Map();
    for (const type of this.actorTypes()) {
      const model = CONFIG.Actor?.dataModels?.[type];
      if (!model) continue;
      try {
        const paths = this.#scanSchema(model.schema, "");
        if (paths.length > 0) types.set(type, paths);
      } catch (error) {
        LogUtil.warn("GenericGroups - could not read schema", [type, error]);
      }
    }
    LogUtil.log("GenericGroups - detected group types", [Object.fromEntries(types)]);
    this.#schemaTypes = types;
    return types;
  }

  /**
   * Member list paths inside a schema
   * @param {foundry.data.fields.SchemaField} schema
   * @param {string} prefix
   * @returns {MemberPath[]}
   */
  static #scanSchema(schema, prefix) {
    const paths = [];
    for (const [name, field] of Object.entries(schema?.fields ?? {})) {
      const path = prefix ? `${prefix}.${name}` : name;
      if (field instanceof foundry.data.fields.ArrayField) {
        const element = field.element;
        if (this.#isActorRefField(element, name)) {
          paths.push({ path, key: null, ref: this.#refKind(element) });
        } else if (element instanceof foundry.data.fields.SchemaField) {
          const key = Object.entries(element.fields).find(([subName, sub]) => this.#isActorRefField(sub, subName))?.[0];
          if (key) paths.push({ path, key, ref: this.#refKind(element.fields[key]) });
        }
      } else if (field instanceof foundry.data.fields.SchemaField) {
        paths.push(...this.#scanSchema(field, path));
      }
    }
    return paths;
  }

  /**
   * How an actor reference field stores its value
   * @param {foundry.data.fields.DataField} field
   * @returns {"id"|"uuid"}
   */
  static #refKind(field) {
    return field instanceof foundry.data.fields.ForeignDocumentField ? "id" : "uuid";
  }

  /**
   * Creation data that stores actors as the members of a new actor of the type, empty when the
   * type's member field is unknown
   * @param {string} type
   * @param {Actor[]} actors
   * @returns {Object}
   */
  static memberData(type, actors) {
    const memberPath = this.#getSchemaTypes().get(type)?.find(entry => entry.ref);
    if (!memberPath) return {};
    const entries = actors.map(actor => {
      const ref = memberPath.ref === "id" ? actor.id : actor.uuid;
      return memberPath.key ? { [memberPath.key]: ref } : ref;
    });
    return foundry.utils.expandObject({ [`system.${memberPath.path}`]: entries });
  }

  /**
   * Whether a field stores a reference to a world Actor. Untyped UUID fields and plain string fields
   * (e.g. WoD5e's `members` list of actor UUIDs) count when their name is clearly about members.
   * @param {foundry.data.fields.DataField} field
   * @param {string} name - Field name, or the list's name for list entries
   * @returns {boolean}
   */
  static #isActorRefField(field, name) {
    const fields = foundry.data.fields;
    if (field instanceof fields.ForeignDocumentField) return field.model?.documentName === "Actor";
    if (field instanceof fields.DocumentUUIDField) {
      if (field.type) return field.type === "Actor";
      return MEMBER_KEY_PATTERN.test(name);
    }
    if (field?.constructor === fields.StringField) return PLAIN_MEMBER_KEY_PATTERN.test(name);
    return false;
  }

  /**
   * Member list paths found by looking at the data of an actor whose type has no data model
   * @param {Actor} actor
   * @returns {MemberPath[]}
   */
  static #probePaths(actor) {
    const paths = [];
    const visit = (data, prefix, depth) => {
      for (const [name, value] of Object.entries(data ?? {})) {
        const path = prefix ? `${prefix}.${name}` : name;
        if (Array.isArray(value) && value.length > 0) {
          if (value.every(entry => this.#looksLikeActorRef(entry))) {
            paths.push({ path, key: null, ref: null });
          } else if (value.every(entry => entry && typeof entry === "object")) {
            const key = ["actor", "uuid", "id", "actorId"].find(k => value.every(entry => this.#looksLikeActorRef(entry[k])));
            if (key) paths.push({ path, key, ref: null });
          }
        } else if (value && typeof value === "object" && !Array.isArray(value) && depth < 2) {
          visit(value, path, depth + 1);
        }
      }
    };
    visit(actor?.system, "", 0);
    return paths;
  }

  /**
   * Whether a stored value points at a world Actor
   * @param {*} value
   * @returns {boolean}
   */
  static #looksLikeActorRef(value) {
    if (value instanceof Actor) return true;
    if (typeof value !== "string") return false;
    return value.startsWith("Actor.") || !!game.actors.get(value);
  }

  /**
   * Entries of a member list, whether stored as an array or a set
   * @param {Actor} actor
   * @param {string} path
   * @returns {Array}
   */
  static #entries(actor, path) {
    const value = foundry.utils.getProperty(actor?.system ?? {}, path);
    if (Array.isArray(value)) return value;
    if (value instanceof Set) return Array.from(value);
    return [];
  }

  /**
   * Resolve a stored reference: an Actor, a lazy getter, an id, a UUID or an object carrying one
   * @param {*} ref
   * @returns {Promise<Actor|null>}
   */
  static async #resolveActor(ref) {
    if (typeof ref === "function") ref = ref();
    if (ref instanceof Actor) return ref;
    if (ref && typeof ref === "object") ref = ref.uuid ?? ref.id ?? null;
    if (typeof ref !== "string" || !ref) return null;
    if (!ref.includes(".")) return game.actors.get(ref) ?? null;
    try {
      const doc = await fromUuid(ref);
      return doc instanceof Actor ? doc : null;
    } catch (error) {
      return null;
    }
  }

  /**
   * Actor types the system declares, without the base type
   * @returns {string[]}
   */
  static actorTypes() {
    const types = game.documentTypes?.Actor ?? Object.keys(CONFIG.Actor?.typeLabels ?? {});
    return types.filter(type => type !== CONST.BASE_DOCUMENT_TYPE);
  }

  /**
   * Whether the type name reads like a group
   * @param {string} type
   * @returns {boolean}
   */
  static #isNamedGroupType(type) {
    return GROUP_TYPE_PATTERN.test(type);
  }
}
