import { LANG_PREFIX } from "../constants/General.mjs";
import { AdapterRegistry } from "../core/AdapterRegistry.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";
import { ActorResolver } from "../actors/ActorResolver.mjs";
import { StatusEffectCatalog } from "./StatusEffectCatalog.mjs";
import { StatusEffectMatcher } from "./StatusEffectMatcher.mjs";
import { NotifyUtil } from "../utils/NotifyUtil.mjs";

/**
 * Applies, removes and toggles status effects on actors. Uses the adapter's conditions section
 * when it defines apply / remove, otherwise Actor#toggleStatusEffect, otherwise raw ActiveEffects.
 * @module conditions/StatusEffectActions
 */
export class StatusEffectActions {
  /**
   * Localise a notification key
   * @param {string} key
   * @param {Object} [data]
   * @returns {string}
   */
  static #notify(key, data = {}) {
    return game.i18n.format(`${LANG_PREFIX}.notifications.${key}`, data);
  }

  /**
   * Display name of a status effect
   * @param {Object} statusEffect
   * @returns {string}
   */
  static #effectName(statusEffect) {
    if (statusEffect.displayName) return statusEffect.displayName;
    const rawName = statusEffect.name || statusEffect.label || statusEffect.id;
    return game.i18n.localize(rawName) || rawName;
  }

  /**
   * Resolve a status id and a menu selection, warning the user when either is missing
   * @param {string} statusId
   * @param {{selectedActors: Set<string>}} menu
   * @returns {Object|null} The status effect, or null when the action cannot run
   */
  static #prepare(statusId, menu) {
    const statusEffect = StatusEffectCatalog.getStatusEffect(statusId);
    if (!statusEffect) {
      NotifyUtil.warn(this.#notify("statusEffectNotFound", { effectId: statusId }));
      return null;
    }
    if (menu.selectedActors.size === 0) {
      NotifyUtil.warn(this.#notify("noActorsSelected"));
      return null;
    }
    return statusEffect;
  }

  /**
   * Run an action on every actor behind the unique ids
   * @param {Iterable<string>} uniqueIds
   * @param {function(Actor): Promise<boolean>} action
   * @returns {Promise<{success: number, total: number}>}
   */
  static async #forEachActor(uniqueIds, action) {
    let success = 0;
    let total = 0;
    for (const participant of ActorResolver.resolveParticipants(uniqueIds)) {
      total++;
      if (await action(participant.actor)) success++;
    }
    return { success, total };
  }

  /**
   * Apply a status effect to an actor
   * @param {Object} statusEffect - Catalog entry
   * @param {Actor} actor
   * @returns {Promise<boolean>} Whether the effect was added
   */
  static async applyToActor(statusEffect, actor) {
    try {
      const adapterApply = AdapterRegistry.active.conditions?.apply;
      if (typeof adapterApply === "function") {
        return !!(await adapterApply(statusEffect, actor));
      }
      if (StatusEffectMatcher.findEffect(actor, statusEffect.id)) {
        return false;
      }
      if (actor.toggleStatusEffect) {
        await actor.toggleStatusEffect(statusEffect.id, { active: true });
        return true;
      }
      const effectData = {
        name: statusEffect.name || statusEffect.label || statusEffect.id,
        img: statusEffect.img || statusEffect.icon,
        statuses: [statusEffect.id],
        flags: { core: { statusId: statusEffect.id } }
      };
      if (statusEffect.changes) {
        effectData.changes = statusEffect.changes;
      }
      await actor.createEmbeddedDocuments("ActiveEffect", [effectData]);
      return true;
    } catch (error) {
      LogUtil.error(`StatusEffectActions.applyToActor - ${actor?.name}`, [error]);
      return false;
    }
  }

  /**
   * Remove a status effect from an actor
   * @param {Object} statusEffect - Catalog entry
   * @param {Actor} actor
   * @returns {Promise<boolean>} Whether an effect was removed
   */
  static async removeFromActor(statusEffect, actor) {
    try {
      const adapterRemove = AdapterRegistry.active.conditions?.remove;
      if (typeof adapterRemove === "function") {
        return !!(await adapterRemove(statusEffect, actor));
      }
      const existingEffect = StatusEffectMatcher.findEffect(actor, statusEffect.id);
      if (!existingEffect) {
        return false;
      }
      if (actor.toggleStatusEffect) {
        await actor.toggleStatusEffect(statusEffect.id, { active: false });
        return true;
      }
      await existingEffect.delete();
      return true;
    } catch (error) {
      LogUtil.error(`StatusEffectActions.removeFromActor - ${actor?.name}`, [error]);
      return false;
    }
  }

  /**
   * Apply the effect when absent, remove it when present
   * @param {Object} statusEffect - Catalog entry
   * @param {Actor} actor
   * @returns {Promise<boolean>}
   */
  static async toggleOnActor(statusEffect, actor) {
    if (StatusEffectMatcher.hasEffect(actor, statusEffect.id)) {
      return this.removeFromActor(statusEffect, actor);
    }
    return this.applyToActor(statusEffect, actor);
  }

  /**
   * Apply a status to the given actors and report the count
   * @param {Object} statusEffect - Catalog entry
   * @param {Iterable<string>} uniqueIds
   * @returns {Promise<{success: number, total: number}>}
   */
  static async #applyToUniqueIds(statusEffect, uniqueIds) {
    const result = await this.#forEachActor(uniqueIds, actor => this.applyToActor(statusEffect, actor));
    if (result.success > 0) {
      NotifyUtil.info(this.#notify("statusEffectApplied", { effectName: this.#effectName(statusEffect), ...result }));
    }
    return result;
  }

  /**
   * Remove a status from the given actors and report the count
   * @param {Object} statusEffect - Catalog entry
   * @param {Iterable<string>} uniqueIds
   * @returns {Promise<{success: number, total: number}>}
   */
  static async #removeFromUniqueIds(statusEffect, uniqueIds) {
    const result = await this.#forEachActor(uniqueIds, actor => this.removeFromActor(statusEffect, actor));
    if (result.success > 0) {
      NotifyUtil.info(this.#notify("statusEffectRemoved", { effectName: this.#effectName(statusEffect), ...result }));
    }
    return result;
  }

  /**
   * Apply a status to every selected actor
   * @param {string} statusId
   * @param {{selectedActors: Set<string>, currentTab: string}} menu
   */
  static async applyToSelected(statusId, menu) {
    const statusEffect = this.#prepare(statusId, menu);
    if (!statusEffect) return;
    await this.#applyToUniqueIds(statusEffect, menu.selectedActors);
  }

  /**
   * Remove a status from every selected actor
   * @param {string} statusId
   * @param {{selectedActors: Set<string>, currentTab: string}} menu
   */
  static async removeFromSelected(statusId, menu) {
    const statusEffect = this.#prepare(statusId, menu);
    if (!statusEffect) return;
    await this.#removeFromUniqueIds(statusEffect, menu.selectedActors);
  }

  /**
   * Remove the status from all given actors when any of them has it, otherwise apply it to all
   * @param {string} statusId
   * @param {Iterable<string>} uniqueIds
   */
  static async toggleOnUniqueIds(statusId, uniqueIds) {
    const statusEffect = StatusEffectCatalog.getStatusEffect(statusId);
    if (!statusEffect) {
      NotifyUtil.warn(this.#notify("statusEffectNotFound", { effectId: statusId }));
      return;
    }
    const ids = Array.from(uniqueIds ?? []);
    const anyHasEffect = ActorResolver.resolveParticipants(ids)
      .some(participant => StatusEffectMatcher.hasEffect(participant.actor, statusId));
    if (anyHasEffect) {
      await this.#removeFromUniqueIds(statusEffect, ids);
    } else {
      await this.#applyToUniqueIds(statusEffect, ids);
    }
  }

  /**
   * Toggle a status on the selection
   * @param {string} statusId
   * @param {{selectedActors: Set<string>, currentTab: string}} menu
   */
  static async toggleOnSelected(statusId, menu) {
    if (!this.#prepare(statusId, menu)) return;
    await this.toggleOnUniqueIds(statusId, menu.selectedActors);
  }

  /**
   * Remove every catalogued status found on the given actors
   * @param {Iterable<string>} uniqueIds
   * @returns {Promise<{removed: number, actors: number}>}
   */
  static async removeAllFromUniqueIds(uniqueIds) {
    const participants = ActorResolver.resolveParticipants(uniqueIds);
    const statusIds = new Set();
    for (const participant of participants) {
      for (const effect of StatusEffectMatcher.getAllEffects(participant.actor)) {
        effect.statuses?.forEach?.(statusId => statusIds.add(statusId));
      }
    }
    if (statusIds.size === 0) {
      NotifyUtil.info(this.#notify("noStatusEffectsToRemove"));
      return { removed: 0, actors: participants.length };
    }
    let removed = 0;
    for (const statusId of statusIds) {
      const statusEffect = StatusEffectCatalog.getStatusEffect(statusId);
      if (!statusEffect) continue;
      for (const participant of participants) {
        if (await this.removeFromActor(statusEffect, participant.actor)) removed++;
      }
    }
    if (removed > 0) {
      NotifyUtil.info(this.#notify("statusEffectsRemoved", { count: removed, actors: participants.length }));
    } else if (participants.length > 0) {
      NotifyUtil.info(this.#notify("noStatusEffectsToRemove"));
    }
    return { removed, actors: participants.length };
  }

  /**
   * Remove every status from the selected actors
   * @param {{selectedActors: Set<string>, currentTab: string}} menu
   */
  static async removeAllFromSelected(menu) {
    if (menu.selectedActors.size === 0) {
      NotifyUtil.warn(this.#notify("noActorsSelected"));
      return;
    }
    await this.removeAllFromUniqueIds(menu.selectedActors);
  }
}
