import { MODULE_ID, FLAGS } from "../constants/General.mjs";
import { getSettings } from "../constants/Settings.mjs";
import { SettingsUtil } from "../utils/SettingsUtil.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";

/**
 * Automatic movement locks during combat: every combatant that is not on its turn is locked
 * under FLAGS.TOKEN.COMBAT_MOVEMENT_RESTRICTED while the "auto block movement in combat"
 * setting is enabled. Only the GM client writes these flags.
 * @module tokens/TokenCombatMovement
 */
export class TokenCombatMovement {
  /**
   * Whether this client should apply combat locks
   * @returns {boolean}
   */
  static isActive() {
    if (!game.user.isGM) return false;
    return !!SettingsUtil.get(getSettings().autoBlockMovementInCombat.tag);
  }

  /**
   * Set or clear the combat lock on tokens. Clearing only touches tokens carrying a combat lock.
   * @param {TokenDocument[]} tokenDocs
   * @param {boolean} restricted
   * @returns {Promise<void>}
   */
  static async setCombatMovementRestriction(tokenDocs, restricted) {
    const updates = [];
    for (const tokenDoc of tokenDocs) {
      if (restricted) {
        updates.push({
          _id: tokenDoc.id,
          [`flags.${MODULE_ID}.${FLAGS.TOKEN.COMBAT_MOVEMENT_RESTRICTED}`]: {
            enabled: true,
            restrictedAt: Date.now(),
            combatId: game.combat?.id ?? null
          }
        });
      } else if (this.hasCombatRestriction(tokenDoc)) {
        updates.push({
          _id: tokenDoc.id,
          [`flags.${MODULE_ID}.-=${FLAGS.TOKEN.COMBAT_MOVEMENT_RESTRICTED}`]: null
        });
      }
    }
    if (updates.length === 0) return;

    const byScene = new Map();
    for (const update of updates) {
      const scene = tokenDocs.find(doc => doc.id === update._id)?.parent;
      if (!scene) continue;
      if (!byScene.has(scene)) byScene.set(scene, []);
      byScene.get(scene).push(update);
    }
    try {
      for (const [scene, sceneUpdates] of byScene) {
        await scene.updateEmbeddedDocuments("Token", sceneUpdates);
      }
      LogUtil.log("TokenCombatMovement.setCombatMovementRestriction", [restricted, updates.length]);
    } catch (error) {
      LogUtil.error("TokenCombatMovement: failed to update combat movement restrictions", [error]);
    }
  }

  /**
   * Whether a token carries a combat lock
   * @param {TokenDocument} tokenDoc
   * @returns {boolean}
   */
  static hasCombatRestriction(tokenDoc) {
    return tokenDoc.getFlag(MODULE_ID, FLAGS.TOKEN.COMBAT_MOVEMENT_RESTRICTED)?.enabled === true;
  }

  /**
   * Lock every combatant except the active one
   * @param {Combat} combat
   * @returns {Promise<void>}
   */
  static async lockAllButCurrent(combat) {
    const currentTokenId = combat.combatant?.tokenId;
    const toLock = [];
    const toUnlock = [];
    for (const combatant of combat.combatants) {
      const tokenDoc = combatant.token;
      if (!tokenDoc) continue;
      if (combatant.tokenId === currentTokenId) {
        toUnlock.push(tokenDoc);
      } else {
        toLock.push(tokenDoc);
      }
    }
    await this.setCombatMovementRestriction(toUnlock, false);
    await this.setCombatMovementRestriction(toLock, true);
  }

  /**
   * Combat started: lock every combatant except the active one
   * @param {Combat} combat
   * @param {Object} updateData
   * @returns {Promise<void>}
   */
  static async onCombatStart(combat, updateData) {
    if (!this.isActive()) return;
    LogUtil.log("TokenCombatMovement.onCombatStart", [combat.id]);
    const currentId = combat.combatant?.id;
    const toLock = [];
    for (const combatant of combat.combatants) {
      if (combatant.id === currentId || !combatant.token) continue;
      toLock.push(combatant.token);
    }
    await this.setCombatMovementRestriction(toLock, true);
  }

  /**
   * Turn changed: unlock the active combatant and lock everyone else
   * @param {Combat} combat
   * @param {Object} prior
   * @param {Object} current
   * @returns {Promise<void>}
   */
  static async onCombatTurnChange(combat, prior, current) {
    if (!this.isActive()) return;
    LogUtil.log("TokenCombatMovement.onCombatTurnChange", [prior, current]);
    await this.lockAllButCurrent(combat);
  }

  /**
   * Combat ended: remove every combat lock from its combatants
   * @param {Combat} combat
   * @returns {Promise<void>}
   */
  static async onCombatEnd(combat) {
    if (!game.user.isGM) return;
    LogUtil.log("TokenCombatMovement.onCombatEnd", [combat.id]);
    const toUnlock = [];
    for (const combatant of combat.combatants) {
      const tokenDoc = combatant.token;
      if (tokenDoc && this.hasCombatRestriction(tokenDoc)) {
        toUnlock.push(tokenDoc);
      }
    }
    await this.setCombatMovementRestriction(toUnlock, false);
  }

  /**
   * Combatant added to a running combat: lock it unless it is the active one
   * @param {Combatant} combatant
   * @param {Object} options
   * @param {string} userId
   * @returns {Promise<void>}
   */
  static async onCreateCombatant(combatant, options, userId) {
    if (!this.isActive()) return;
    const combat = combatant.combat;
    if (!combat?.started || !combatant.token) return;
    if (combatant.id === combat.combatant?.id) return;
    LogUtil.log("TokenCombatMovement.onCreateCombatant", [combatant.name]);
    await this.setCombatMovementRestriction([combatant.token], true);
  }

  /**
   * Apply combat locks for a combat that was already running when the client loaded
   * @returns {Promise<void>}
   */
  static async initializeCombatMovementRestrictions() {
    if (!this.isActive()) return;
    const combat = game.combat;
    if (!combat?.started) return;
    LogUtil.log("TokenCombatMovement.initializeCombatMovementRestrictions", [combat.id]);
    await this.lockAllButCurrent(combat);
  }
}
