import { MODULE_ID, FLAGS, LANG_PREFIX } from "../constants/General.mjs";
import { HOOKS_MODULE } from "../constants/Hooks.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";
import { NotifyUtil } from "../utils/NotifyUtil.mjs";

/**
 * Reads and writes the favourite / blocked flags stored on actors. Favourites are always listed
 * in the bar, blocked actors never are. Every change asks the menu to re-render through the
 * `flash-token-bar.refreshMenu` hook.
 * @module actors/ActorStatusFlags
 */
export class ActorStatusFlags {
  /**
   * Resolve an actor or actor id into an actor document
   * @param {Actor|string} actorOrId
   * @returns {Actor|null}
   */
  static #resolve(actorOrId) {
    if (!actorOrId) return null;
    const actor = typeof actorOrId === "string" ? game.actors.get(actorOrId) : actorOrId;
    return actor?.getFlag ? actor : null;
  }

  /**
   * Actor id carried by an actor directory entry (HTMLElement in v13+, jQuery in older cores)
   * @param {HTMLElement|Object} li
   * @returns {string|undefined}
   */
  static #entryActorId(li) {
    const element = li?.[0] ?? li;
    return element?.dataset?.entryId ?? element?.dataset?.documentId ?? li?.data?.("documentId");
  }

  /**
   * Ask the token bar to re-render
   */
  static #refreshMenu() {
    Hooks.callAll(HOOKS_MODULE.REFRESH_MENU);
  }

  /**
   * Whether the actor is marked as a favourite
   * @param {Actor|string} actor - Actor or actor id
   * @returns {boolean}
   */
  static isFavorite(actor) {
    try {
      const actorDoc = this.#resolve(actor);
      return actorDoc?.getFlag(MODULE_ID, FLAGS.ACTOR.FAVORITE) === true;
    } catch (error) {
      LogUtil.error("ActorStatusFlags.isFavorite", [error, actor]);
      return false;
    }
  }

  /**
   * Whether the actor is blocked from the bar
   * @param {Actor|string} actor - Actor or actor id
   * @returns {boolean}
   */
  static isBlocked(actor) {
    const actorDoc = this.#resolve(actor);
    return actorDoc?.getFlag(MODULE_ID, FLAGS.ACTOR.BLOCKED) === true;
  }

  /**
   * Set the favourite flag. Favouriting also clears the blocked flag.
   * @param {Actor|string} actor - Actor or actor id
   * @param {boolean} isFavorite
   * @returns {Promise<void>}
   */
  static async setFavorite(actor, isFavorite) {
    const actorDoc = this.#resolve(actor);
    if (!actorDoc) {
      LogUtil.error("ActorStatusFlags.setFavorite - actor not found", [actor]);
      return;
    }
    LogUtil.log("ActorStatusFlags.setFavorite", [actorDoc.name, isFavorite]);
    if (isFavorite) {
      await actorDoc.setFlag(MODULE_ID, FLAGS.ACTOR.FAVORITE, true);
      await actorDoc.unsetFlag(MODULE_ID, FLAGS.ACTOR.BLOCKED);
    } else {
      await actorDoc.unsetFlag(MODULE_ID, FLAGS.ACTOR.FAVORITE);
    }
    this.#refreshMenu();
  }

  /**
   * Set the blocked flag and notify the user. Blocking also clears the favourite flag.
   * @param {Actor|string} actor - Actor or actor id
   * @param {boolean} isBlocked
   * @returns {Promise<void>}
   */
  static async setBlocked(actor, isBlocked) {
    const actorDoc = this.#resolve(actor);
    if (!actorDoc) {
      LogUtil.error("ActorStatusFlags.setBlocked - actor not found", [actor]);
      return;
    }
    LogUtil.log("ActorStatusFlags.setBlocked", [actorDoc.name, isBlocked]);
    if (isBlocked) {
      await actorDoc.setFlag(MODULE_ID, FLAGS.ACTOR.BLOCKED, true);
      await actorDoc.unsetFlag(MODULE_ID, FLAGS.ACTOR.FAVORITE);
    } else {
      await actorDoc.unsetFlag(MODULE_ID, FLAGS.ACTOR.BLOCKED);
    }
    const key = isBlocked ? "actorBlocked" : "actorUnblocked";
    NotifyUtil.info(game.i18n.format(`${LANG_PREFIX}.notifications.${key}`, { actor: actorDoc.name }));
    this.#refreshMenu();
  }

  /**
   * Toggle the favourite flag, or force it when a boolean is given
   * @param {Actor|string} actor - Actor or actor id
   * @param {boolean} [makeFavorite] - Explicit target state
   * @returns {Promise<void>}
   */
  static async toggleFavorite(actor, makeFavorite) {
    const isFavorite = typeof makeFavorite === "boolean" ? makeFavorite : !this.isFavorite(actor);
    await this.setFavorite(actor, isFavorite);
  }

  /**
   * Toggle the blocked flag, or force it when a boolean is given
   * @param {Actor|string} actor - Actor or actor id
   * @param {boolean} [makeBlocked] - Explicit target state
   * @returns {Promise<void>}
   */
  static async toggleBlocked(actor, makeBlocked) {
    const isBlocked = typeof makeBlocked === "boolean" ? makeBlocked : !this.isBlocked(actor);
    await this.setBlocked(actor, isBlocked);
  }

  /**
   * Block an actor (drag-to-remove)
   * @param {Actor|string} actor - Actor or actor id
   * @returns {Promise<void>}
   */
  static async blockActor(actor) {
    await this.setBlocked(actor, true);
  }

  /**
   * All favourite actors
   * @returns {Actor[]}
   */
  static getFavoriteActors() {
    return game.actors.filter(actor => this.isFavorite(actor));
  }

  /**
   * All blocked actors
   * @returns {Actor[]}
   */
  static getBlockedActors() {
    return game.actors.filter(actor => this.isBlocked(actor));
  }

  /**
   * Remove blocked actors from a list
   * @param {Actor[]} actors
   * @returns {Actor[]}
   */
  static filterBlocked(actors) {
    return actors.filter(actor => !this.isBlocked(actor));
  }

  /**
   * Both flags for an actor
   * @param {Actor|string} actor - Actor or actor id
   * @returns {{isFavorite: boolean, isBlocked: boolean}}
   */
  static getActorStatus(actor) {
    return {
      isFavorite: this.isFavorite(actor),
      isBlocked: this.isBlocked(actor)
    };
  }

  /**
   * Clear both flags
   * @param {Actor|string} actor - Actor or actor id
   * @returns {Promise<void>}
   */
  static async clearActorStatus(actor) {
    const actorDoc = this.#resolve(actor);
    if (!actorDoc) return;
    await actorDoc.unsetFlag(MODULE_ID, FLAGS.ACTOR.FAVORITE);
    await actorDoc.unsetFlag(MODULE_ID, FLAGS.ACTOR.BLOCKED);
    this.#refreshMenu();
  }

  /**
   * Add the favourite toggle plus the block / unblock entries to an actor context menu
   * @param {HTMLElement} html - Directory element
   * @param {Array} options - Existing context menu options
   * @returns {Array} The same options array
   */
  static getContextMenuOptions(html, options) {
    if (!game.user.isGM) return options;
    options.push({
      name: game.i18n.localize(`${LANG_PREFIX}.contextMenu.toggleFavorite`),
      icon: '<i class="fas fa-bolt"></i>',
      callback: li => {
        const actorId = this.#entryActorId(li);
        if (actorId) this.toggleFavorite(actorId);
        return actorId;
      },
      condition: () => game.user.isGM
    });
    this.registerContextOptions(html, options);
    return options;
  }

  /**
   * Add the "block from token bar" / "unblock from token bar" entries used by the
   * getActorContextOptions hook. Only GMs see them.
   * @param {HTMLElement} html - Directory element
   * @param {Array} contextOptions - Context menu options to extend in place
   */
  static registerContextOptions(html, contextOptions) {
    LogUtil.log("ActorStatusFlags.registerContextOptions", [html, contextOptions]);
    if (!game.user.isGM) return;
    contextOptions.push({
      name: game.i18n.localize(`${LANG_PREFIX}.contextMenu.unblockFromMenu`),
      icon: '<i class="fas fa-users"></i>',
      callback: li => {
        const actorId = this.#entryActorId(li);
        if (actorId) this.toggleBlocked(actorId, false);
        return actorId;
      },
      condition: li => this.isBlocked(this.#entryActorId(li))
    });
    contextOptions.push({
      name: game.i18n.localize(`${LANG_PREFIX}.contextMenu.blockFromMenu`),
      icon: '<i class="fas fa-ban"></i>',
      callback: li => {
        const actorId = this.#entryActorId(li);
        if (actorId) this.toggleBlocked(actorId, true);
        return actorId;
      },
      condition: li => !this.isBlocked(this.#entryActorId(li))
    });
  }
}
