import { MODULE_ID, FLAGS, LANG_PREFIX } from "../constants/General.mjs";
import { HOOKS_MODULE } from "../constants/Hooks.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";
import { ActorResolver } from "../actors/ActorResolver.mjs";
import { TokenCombatMovement } from "./TokenCombatMovement.mjs";
import { NotifyUtil } from "../utils/NotifyUtil.mjs";

/**
 * GM controlled token movement restrictions. Manual locks are stored under
 * FLAGS.TOKEN.MOVEMENT_RESTRICTED; combat driven locks are handled by TokenCombatMovement
 * and stored under FLAGS.TOKEN.COMBAT_MOVEMENT_RESTRICTED. Either flag blocks player movement,
 * the GM can always move tokens.
 * @module tokens/TokenMovementLock
 */
export class TokenMovementLock {
  /**
   * Toggle the movement lock for the actors selected in the menu
   * @param {{selectedActors: Set<string>, currentTab: string}} menu
   * @returns {Promise<void>}
   */
  static async toggleMovementForSelected(menu) {
    if (menu.selectedActors.size === 0) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.noValidActorsSelected`));
      return;
    }
    await this.toggleForUniqueIds(menu.selectedActors);
  }

  /**
   * Toggle the movement lock for a list of unique ids. Majority rule: when fewer tokens are
   * locked than unlocked every token gets locked, otherwise every token gets unlocked.
   * @param {Iterable<string>} uniqueIds
   * @returns {Promise<void>}
   */
  static async toggleForUniqueIds(uniqueIds) {
    const tokenDocs = this.getTokenDocsForUniqueIds(uniqueIds);
    if (tokenDocs.length === 0) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.noTokensForMovementLock`));
      return;
    }

    const status = this.getMovementStatus(tokenDocs);
    const shouldLock = status.restricted < status.unrestricted;
    LogUtil.log("TokenMovementLock.toggleForUniqueIds", [status, shouldLock]);

    await this.setMovementRestriction(tokenDocs, shouldLock);
    Hooks.callAll(HOOKS_MODULE.REFRESH_MENU);

    const messageKey = shouldLock ? "movementLocked" : "movementUnlocked";
    NotifyUtil.info(game.i18n.format(`${LANG_PREFIX}.notifications.${messageKey}`, { count: tokenDocs.length }));
  }

  /**
   * Token documents in the current scene for a list of unique ids. A token id resolves to that
   * token; an actor id resolves to every token of the actor in the scene.
   * @param {Iterable<string>} uniqueIds
   * @returns {TokenDocument[]}
   */
  static getTokenDocsForUniqueIds(uniqueIds) {
    const tokenDocs = [];
    const seen = new Set();
    for (const uniqueId of uniqueIds ?? []) {
      const participant = ActorResolver.resolveParticipant(uniqueId);
      if (!participant) {
        LogUtil.log("TokenMovementLock: no actor for uniqueId", [uniqueId]);
        continue;
      }
      const docs = participant.tokenDoc ? [participant.tokenDoc] : ActorResolver.getSceneTokens(participant.actorId);
      for (const doc of docs) {
        if (seen.has(doc.id)) continue;
        seen.add(doc.id);
        tokenDocs.push(doc);
      }
    }
    return tokenDocs;
  }

  /**
   * Set or clear the manual movement lock. Clearing also removes any combat lock so the GM
   * can momentarily free a token during combat.
   * @param {TokenDocument[]} tokenDocs
   * @param {boolean} restricted
   * @returns {Promise<void>}
   */
  static async setMovementRestriction(tokenDocs, restricted) {
    const updates = tokenDocs.map(tokenDoc => {
      if (restricted) {
        return {
          _id: tokenDoc.id,
          [`flags.${MODULE_ID}.${FLAGS.TOKEN.MOVEMENT_RESTRICTED}`]: {
            enabled: true,
            restrictedAt: Date.now(),
            restrictedBy: game.user.id
          }
        };
      }
      return {
        _id: tokenDoc.id,
        [`flags.${MODULE_ID}.-=${FLAGS.TOKEN.MOVEMENT_RESTRICTED}`]: null,
        [`flags.${MODULE_ID}.-=${FLAGS.TOKEN.COMBAT_MOVEMENT_RESTRICTED}`]: null
      };
    });

    try {
      await this.applyTokenUpdates(tokenDocs, updates);
      LogUtil.log("TokenMovementLock.setMovementRestriction", [restricted, updates.length]);
    } catch (error) {
      LogUtil.error("TokenMovementLock: failed to update movement restrictions", [error]);
      NotifyUtil.error(game.i18n.localize(`${LANG_PREFIX}.notifications.movementUpdateFailed`));
    }
  }

  /**
   * Apply embedded token updates, grouping them by the scene that owns each token
   * @param {TokenDocument[]} tokenDocs
   * @param {Object[]} updates - Update objects with an _id matching tokenDocs
   * @returns {Promise<void>}
   */
  static async applyTokenUpdates(tokenDocs, updates) {
    const byScene = new Map();
    for (const update of updates) {
      const tokenDoc = tokenDocs.find(doc => doc.id === update._id);
      const scene = tokenDoc?.parent ?? game.scenes.current;
      if (!scene) continue;
      if (!byScene.has(scene)) byScene.set(scene, []);
      byScene.get(scene).push(update);
    }
    for (const [scene, sceneUpdates] of byScene) {
      await scene.updateEmbeddedDocuments("Token", sceneUpdates);
    }
  }

  /**
   * Whether a token is locked, manually or by combat
   * @param {TokenDocument} tokenDoc
   * @returns {boolean}
   */
  static isMovementRestricted(tokenDoc) {
    const manual = tokenDoc.getFlag(MODULE_ID, FLAGS.TOKEN.MOVEMENT_RESTRICTED);
    const combat = tokenDoc.getFlag(MODULE_ID, FLAGS.TOKEN.COMBAT_MOVEMENT_RESTRICTED);
    return manual?.enabled === true || combat?.enabled === true;
  }

  /**
   * Whether a user may apply a token update. Used from the preUpdateToken hook.
   * @param {TokenDocument} tokenDoc
   * @param {User} user
   * @param {Object} updateData
   * @returns {boolean}
   */
  static isMovementAllowed(tokenDoc, user, updateData) {
    if (user.isGM) return true;
    const hasPositionChange = updateData.x !== undefined || updateData.y !== undefined;
    if (!hasPositionChange) return true;
    if (!this.isMovementRestricted(tokenDoc)) return true;
    LogUtil.log("TokenMovementLock: movement blocked", [tokenDoc.name, user.name]);
    return false;
  }

  /**
   * Lock counts for a list of tokens
   * @param {TokenDocument[]} tokenDocs
   * @returns {{restricted: number, unrestricted: number, total: number, hasRestricted: boolean, hasUnrestricted: boolean, allRestricted: boolean, allUnrestricted: boolean}}
   */
  static getMovementStatus(tokenDocs) {
    let restricted = 0;
    for (const tokenDoc of tokenDocs) {
      if (this.isMovementRestricted(tokenDoc)) restricted++;
    }
    const unrestricted = tokenDocs.length - restricted;
    return {
      restricted,
      unrestricted,
      total: tokenDocs.length,
      hasRestricted: restricted > 0,
      hasUnrestricted: unrestricted > 0,
      allRestricted: restricted === tokenDocs.length,
      allUnrestricted: unrestricted === tokenDocs.length
    };
  }

  /**
   * Font Awesome icon for a movement status
   * @param {{allRestricted: boolean, allUnrestricted: boolean}} status
   * @returns {string}
   */
  static getStatusIcon(status) {
    if (status.allRestricted) return "fa-user-lock";
    if (status.allUnrestricted) return "fa-person-walking";
    return "fa-user-slash";
  }

  /**
   * Remove manual and combat locks from tokens
   * @param {TokenDocument[]} tokenDocs
   * @returns {Promise<void>}
   */
  static async clearAllRestrictions(tokenDocs) {
    await this.setMovementRestriction(tokenDocs, false);
  }

  /**
   * Combat started: lock every combatant except the active one
   * @param {Combat} combat
   * @param {Object} updateData
   * @returns {Promise<void>}
   */
  static onCombatStart(combat, updateData) {
    return TokenCombatMovement.onCombatStart(combat, updateData);
  }

  /**
   * Turn changed: unlock the active combatant and lock everyone else
   * @param {Combat} combat
   * @param {Object} prior
   * @param {Object} current
   * @returns {Promise<void>}
   */
  static onCombatTurnChange(combat, prior, current) {
    return TokenCombatMovement.onCombatTurnChange(combat, prior, current);
  }

  /**
   * Combat ended: remove combat locks
   * @param {Combat} combat
   * @returns {Promise<void>}
   */
  static onCombatEnd(combat) {
    return TokenCombatMovement.onCombatEnd(combat);
  }

  /**
   * Combatant added to a running combat: lock it unless it is the active one
   * @param {Combatant} combatant
   * @param {Object} options
   * @param {string} userId
   * @returns {Promise<void>}
   */
  static onCreateCombatant(combatant, options, userId) {
    return TokenCombatMovement.onCreateCombatant(combatant, options, userId);
  }

  /**
   * Apply combat locks for a combat that was already running when the client loaded
   * @returns {Promise<void>}
   */
  static initializeCombatMovementRestrictions() {
    return TokenCombatMovement.initializeCombatMovementRestrictions();
  }
}
