import { GenericGroups } from "../generic/GenericGroups.mjs";
import { LogUtil } from "../../utils/LogUtil.mjs";
import { RollCallBuilder } from "./RollCallBuilder.mjs";

const ROLL_METHOD_PATTERN = /^(roll|check|test)([A-Z0-9]|$)|[a-z](Roll|Check|Test)$/;
const API_ROLL_PATTERN = /roll|check|test/i;
const ITEM_GROUP_PREFIX = "@items:";
const SHEET_ROLLS_GROUP = "@sheet-rolls";
const SHEET_ROLLS_METHOD = "actor:roll";
const IGNORED_METHODS = new Set(["rollTableResult"]);
const PRIVATE_NAME_PATTERN = /^_|^on[A-Z]/;
const MAX_DEPTH = 3;
const MIN_GROUP_SIZE = 2;
const RESOURCE_KEYS = ["value", "max", "min", "current", "temp", "tempmax"];

/**
 * @typedef {Object} DiscoveredMethod
 * @property {string} id - "actor:rollSkill", "system:rollSkill", "sheet:rollSkill", "item:roll" or "api:WOD5E.api.Roll" (a path from globalThis)
 * @property {"actor"|"system"|"sheet"|"item"|"api"} source - Actor method, system data method, actor sheet method,
 *   method of the owned item behind the chosen option, or system API function
 * @property {string} name - Method name
 * @property {string} label - Human readable name, e.g. "Skill"
 * @property {boolean} takesKey - The method declares at least one parameter
 * @property {boolean} core - Defined by Foundry itself (e.g. rollInitiative), not by the system
 * @property {string} passes - What a call fills in, e.g. "basicDice ← value · actor · difficulty"
 * @property {number} score - How well the roll context fills the method's parameters
 * @property {string[]} types - Actor types that have the method; every type for API functions
 */

/**
 * @typedef {Object} DiscoveredGroup
 * @property {string} path - Path inside actor.system (e.g. "skills"), or "@items:<type>" for owned items of a type (e.g. CoC7 skills)
 * @property {string} label - Human readable name, e.g. "Skills"
 * @property {Array<{key: string, label: string}>} options - Rollable entries of the group
 * @property {string[]} types - Actor types that have the group
 * @property {string} [method] - Method the options are meant for, when the source dictates it (sheet rolls)
 */

/**
 * Lists what a system lets an actor roll without knowing its data model: `roll*` methods on the actor
 * class and its system data, and groups of numeric values in the actor data (skills, attributes...).
 * Every actor type is inspected through an existing world actor, or an unsaved stand-in when the world
 * has none of that type, so the lists are complete in an empty world.
 * @module adapters/configured/SystemRollDiscovery
 */
export class SystemRollDiscovery {
  /**
   * Roll methods, system API roll functions and value groups of every non-group actor type
   * @returns {{methods: DiscoveredMethod[], groups: DiscoveredGroup[]}}
   */
  static discover() {
    const methods = new Map();
    const groups = new Map();
    const samples = this.sampleActors();
    for (const api of this.#apiFunctions()) {
      methods.set(api.id, { ...api, types: Array.from(samples.keys()) });
    }
    for (const [type, actor] of samples) {
      for (const method of this.#methodsOf(actor)) {
        const entry = methods.get(method.id) ?? { ...method, types: [] };
        entry.types.push(type);
        methods.set(method.id, entry);
      }
      for (const group of this.groupsOf(actor)) {
        const entry = groups.get(group.path) ?? { path: group.path, label: group.label, method: group.method, options: [], types: [] };
        entry.types.push(type);
        const known = new Set(entry.options.map(option => option.key));
        for (const option of group.options) {
          if (!known.has(option.key)) entry.options.push(option);
        }
        groups.set(group.path, entry);
      }
    }
    const sortByLabel = (a, b) => b.types.length - a.types.length || a.label.localeCompare(b.label);
    return {
      methods: Array.from(methods.values()).sort(sortByLabel),
      groups: Array.from(groups.values()).sort(sortByLabel)
    };
  }

  /**
   * One actor per non-group type: a world actor when one exists, otherwise an unsaved stand-in.
 * Types starting with an underscore are system internals (e.g. Custom System Builder sheet templates).
   * @returns {Map<string, Actor>}
   */
  static sampleActors() {
    const samples = new Map();
    for (const type of GenericGroups.actorTypes()) {
      if (type.startsWith("_") || GenericGroups.isGroupActor({ type, system: {} })) continue;
      const actor = game.actors.find(entry => entry.type === type) ?? this.#standIn(type);
      if (actor) samples.set(type, actor);
    }
    return samples;
  }

  /**
   * Value groups found in an actor's data
   * @param {Actor} actor
   * @returns {Array<{path: string, label: string, options: Array<{key: string, label: string}>}>}
   */
  static groupsOf(actor) {
    const groups = [];
    const visit = (data, prefix, depth) => {
      for (const [name, value] of this.#entries(data)) {
        if (!this.#isWalkable(value)) continue;
        const path = prefix ? `${prefix}.${name}` : name;
        const options = this.#rollableOptions(value, actor, path);
        if (this.#isResource(options)) continue;
        if (options.length >= MIN_GROUP_SIZE) {
          groups.push({ path, label: this.humanize(name), options });
        } else if (depth < MAX_DEPTH) {
          visit(value, path, depth + 1);
        }
      }
    };
    visit(actor?.system, "", 1);
    return [...this.#sheetRollGroupsOf(actor), ...groups, ...this.#itemGroupsOf(actor)];
  }

  /**
   * Rollable sheet components, for sheet-builder systems that keep rolls on components instead of in data or
   * methods (e.g. Custom System Builder: labels with a roll message in `templateSystem.componentMap`,
   * rolled with `actor.roll(key)`). Detected by shape, so any system built the same way is covered.
   * @param {Actor} actor
   * @returns {Array<{path: string, label: string, method: string, options: Array<{key: string, label: string}>}>}
   */
  static #sheetRollGroupsOf(actor) {
    if (typeof actor?.roll !== "function") return [];
    let componentMap;
    try {
      componentMap = actor.templateSystem?.componentMap;
    } catch (error) {
      return [];
    }
    if (!componentMap || typeof componentMap !== "object") return [];
    const options = [];
    for (const [key, component] of Object.entries(componentMap)) {
      if (typeof component?.getSendToChatFunctions !== "function" || !component._rollMessage) continue;
      const text = actor.system?.props?.[key];
      const label = typeof text === "string" && text.replace(/<[^>]*>/g, "").trim()
        ? text.replace(/<[^>]*>/g, "").trim()
        : (component.tooltip || this.humanize(key));
      options.push({ key, label });
    }
    if (options.length === 0) return [];
    return [{ path: SHEET_ROLLS_GROUP, label: game.i18n.localize("FLASH_TOKEN_BAR.systemConfig.sheetRolls"), method: SHEET_ROLLS_METHOD, options }];
  }

  /**
   * Owned items with a numeric value, grouped by item type, for systems where skills and similar are items
   * @param {Actor} actor
   * @returns {Array<{path: string, label: string, options: Array<{key: string, label: string}>}>}
   */
  static #itemGroupsOf(actor) {
    const byType = new Map();
    for (const item of actor?.items ?? []) {
      if (this.#numericValue(item.system) === null) continue;
      if (!byType.has(item.type)) byType.set(item.type, []);
      byType.get(item.type).push({ key: item.name, label: item.name });
    }
    return Array.from(byType.entries())
      .filter(([, options]) => options.length >= MIN_GROUP_SIZE)
      .map(([type, options]) => {
        const typeLabel = CONFIG.Item?.typeLabels?.[type];
        return { path: `${ITEM_GROUP_PREFIX}${type}`, label: typeLabel ? game.i18n.localize(typeLabel) : this.humanize(type), options };
      });
  }

  /**
   * Owned item of an item group matching an option key (the item name)
   * @param {Actor} actor
   * @param {string} path - "@items:<type>"
   * @param {string} key - Item name
   * @returns {Item|null}
   */
  static itemFor(actor, path, key) {
    const type = path.slice(ITEM_GROUP_PREFIX.length);
    return actor?.items?.find(item => item.type === type && item.name === key) ?? null;
  }

  /**
   * Whether a group path points at owned items rather than actor data
   * @param {string} path
   * @returns {boolean}
   */
  static isItemGroup(path) {
    return String(path ?? "").startsWith(ITEM_GROUP_PREFIX);
  }

  /**
   * Whether a group path points at rollable sheet components
   * @param {string} path
   * @returns {boolean}
   */
  static isSheetRollGroup(path) {
    return path === SHEET_ROLLS_GROUP;
  }

  /**
   * Rollable options of a group on a specific actor, for actors whose entries differ from the sample
   * @param {Actor} actor
   * @param {string} path
   * @returns {Array<{key: string, label: string}>}
   */
  static optionsOf(actor, path) {
    if (this.isSheetRollGroup(path)) return this.#sheetRollGroupsOf(actor)[0]?.options ?? [];
    if (this.isItemGroup(path)) {
      return this.#itemGroupsOf(actor).find(group => group.path === path)?.options ?? [];
    }
    return this.#rollableOptions(foundry.utils.getProperty(actor?.system ?? {}, path), actor, path);
  }

  /**
   * Numeric value of a group entry on an actor
   * @param {Actor} actor
   * @param {string} path - Group path inside actor.system
   * @param {string} key - Entry key
   * @returns {number|null}
   */
  static readValue(actor, path, key) {
    if (this.isSheetRollGroup(path)) return null;
    if (this.isItemGroup(path)) return this.#numericValue(this.itemFor(actor, path, key)?.system);
    const entry = foundry.utils.getProperty(actor?.system ?? {}, `${path}.${key}`);
    return this.#numericValue(entry);
  }

  /**
   * Readable label from a method or property name: "rollAbilityCheck" -> "Ability Check", "skills" -> "Skills"
   * @param {string} name
   * @returns {string}
   */
  static humanize(name) {
    const words = String(name)
      .replace(/^roll(?=[A-Z0-9])/, "")
      .replace(/[_-]+/g, " ")
      .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
      .trim();
    return words.replace(/\b\w/g, letter => letter.toUpperCase());
  }

  /**
   * The value group a roll method most likely takes as its key, by name: rollSkill -> skills
   * @param {DiscoveredMethod} method
   * @param {DiscoveredGroup[]} groups
   * @returns {string} Group path, or "" when no group matches
   */
  static suggestGroup(method, groups) {
    if (!method?.takesKey) return "";
    const methodName = method.name.toLowerCase();
    const match = groups.find(group => {
      const last = group.path.split(/[.:]/).pop().toLowerCase();
      const stem = last.replace(/(ies|es|s)$/, "");
      const probe = stem.slice(0, Math.max(4, stem.length - 1));
      return probe.length >= 3 && methodName.includes(probe);
    });
    return match?.path ?? "";
  }

  /**
   * Roll methods on the actor class chain and on its system data model
   * @param {Actor} actor
   * @returns {Array<Omit<DiscoveredMethod, "types">>}
   */
  static #methodsOf(actor) {
    const found = [];
    const collect = (target, source, stopAt) => {
      const seen = new Set();
      let proto = Object.getPrototypeOf(target);
      while (proto && proto !== stopAt && proto !== Object.prototype) {
        for (const name of Object.getOwnPropertyNames(proto)) {
          if (seen.has(name) || !ROLL_METHOD_PATTERN.test(name) || PRIVATE_NAME_PATTERN.test(name) || IGNORED_METHODS.has(name)) continue;
          const descriptor = Object.getOwnPropertyDescriptor(proto, name);
          if (typeof descriptor?.value !== "function") continue;
          seen.add(name);
          found.push(this.#describeFunction(`${source}:${name}`, source, name, descriptor.value, {
            core: source === "actor" && typeof foundry.documents.Actor.prototype[name] === "function"
          }));
        }
        proto = Object.getPrototypeOf(proto);
      }
    };
    collect(actor, "actor", foundry.abstract.Document.prototype);
    if (actor?.system && typeof actor.system === "object") {
      collect(actor.system, "system", foundry.abstract.DataModel.prototype);
    }
    const sheet = this.#sheetOf(actor);
    if (sheet) collect(sheet, "sheet", null);
    const itemTypes = new Set(this.#itemGroupsOf(actor).map(group => group.path.slice(ITEM_GROUP_PREFIX.length)));
    const seenItemMethods = new Set();
    for (const type of itemTypes) {
      const item = actor.items.find(entry => entry.type === type);
      const before = found.length;
      if (item) collect(item, "item", foundry.abstract.Document.prototype);
      for (const method of found.splice(before)) {
        if (seenItemMethods.has(method.id)) continue;
        seenItemMethods.add(method.id);
        found.push(method);
      }
    }
    return found;
  }

  /**
   * The actor's sheet instance without rendering it, or null when the sheet cannot be built
   * @param {Actor} actor
   * @returns {Object|null}
   */
  static #sheetOf(actor) {
    if (!actor?.id) return null;
    try {
      return actor.sheet ?? null;
    } catch (error) {
      return null;
    }
  }

  /**
   * Places a system may expose an API: `game.system.api`, `game.<id>`, `CONFIG.<ID>`, and any global whose
   * name matches the system id ignoring case and punctuation (e.g. WOD5E, PF2E, CoC7)
   * @returns {string[]} Paths from globalThis
   */
  static #apiRoots() {
    const id = game.system?.id ?? "";
    const normalized = id.toLowerCase().replace(/[^a-z0-9]/g, "");
    const roots = new Set(["game.system.api", `game.${id}`, `CONFIG.${id.toUpperCase()}`]);
    if (!normalized) return Array.from(roots);
    for (const name of Object.keys(globalThis)) {
      if (name.toLowerCase().replace(/[^a-z0-9]/g, "") === normalized) roots.add(name);
    }
    return Array.from(roots);
  }

  /**
   * Roll functions a system exposes as an API: functions with "roll" in their name on an API root
   * and on its `api`, `dice` and `rolls` objects
   * @returns {Array<Omit<DiscoveredMethod, "types">>}
   */
  static #apiFunctions() {
    const found = new Map();
    for (const root of this.#apiRoots()) {
      for (const path of [root, `${root}.api`, `${root}.dice`, `${root}.rolls`, `${root}.macros`]) {
        const target = foundry.utils.getProperty(globalThis, path);
        if (!target || (typeof target !== "object" && typeof target !== "function")) continue;
        for (const name of Object.keys(target)) {
          const fn = target[name];
          if (typeof fn !== "function" || !API_ROLL_PATTERN.test(name) || PRIVATE_NAME_PATTERN.test(name) || /^class[\s{]/.test(Function.prototype.toString.call(fn))) continue;
          const id = `api:${path}.${name}`;
          if (!found.has(id)) found.set(id, this.#describeFunction(id, "api", name, fn, { core: false, label: `${this.humanize(name)} (${path})` }));
        }
      }
    }
    return Array.from(found.values());
  }

  /**
   * Discovery entry for a roll function
   * @param {string} id
   * @param {"actor"|"system"|"api"} source
   * @param {string} name
   * @param {Function} fn
   * @param {{core: boolean, label?: string}} extra
   * @returns {Omit<DiscoveredMethod, "types">}
   */
  static #describeFunction(id, source, name, fn, extra) {
    return {
      id,
      source,
      name,
      label: extra.label ?? this.humanize(name),
      takesKey: fn.length > 0 || RollCallBuilder.parseParams(fn).names.length > 0,
      core: extra.core,
      passes: RollCallBuilder.describe(fn),
      score: RollCallBuilder.score(fn)
    };
  }

  /**
   * Resolve a discovered method id to the function and the object to call it on
   * @param {string} methodId
   * @param {Actor} actor
   * @param {{group?: string, key?: string}} [option] - Chosen option, needed to find the item for item methods
   * @returns {{fn: Function, thisArg: Object}|null}
   */
  static resolveMethod(methodId, actor, { group = "", key = "" } = {}) {
    const separator = methodId.indexOf(":");
    const source = methodId.slice(0, separator);
    const path = methodId.slice(separator + 1);
    if (source === "api") {
      const parentPath = path.split(".").slice(0, -1).join(".");
      const fn = foundry.utils.getProperty(globalThis, path);
      return typeof fn === "function" ? { fn, thisArg: foundry.utils.getProperty(globalThis, parentPath) } : null;
    }
    const targets = {
      actor: () => actor,
      system: () => actor?.system,
      sheet: () => this.#sheetOf(actor),
      item: () => this.isItemGroup(group) && key ? this.itemFor(actor, group, key) : null
    };
    const thisArg = targets[source]?.() ?? null;
    const fn = thisArg?.[path];
    return typeof fn === "function" ? { fn, thisArg } : null;
  }

  /**
   * Second key of a two-key roll, read from the chosen entry (e.g. the attribute a skill is linked to)
   * @param {Actor} actor
   * @param {string} group
   * @param {string} key
   * @param {string} fromPath - Path inside the entry (or the item's system data) holding the second key
   * @returns {string|null}
   */
  static readSecondKey(actor, group, key, fromPath) {
    if (!group || !key || !fromPath) return null;
    const entry = this.isItemGroup(group)
      ? this.itemFor(actor, group, key)?.system
      : foundry.utils.getProperty(actor?.system ?? {}, `${group}.${key}`);
    const value = foundry.utils.getProperty(entry ?? {}, fromPath);
    return typeof value === "string" && value ? value : null;
  }

  /**
   * Entries of a group that hold a numeric value, labelled from the entry's own label when it has one
   * @param {*} data
   * @returns {Array<{key: string, label: string}>}
   */
  static #rollableOptions(data, actor = null, path = "") {
    if (!this.#isWalkable(data)) return [];
    const options = [];
    for (const [key, entry] of this.#entries(data)) {
      if (this.#numericValue(entry) === null) continue;
      options.push({ key, label: this.#entryLabel(key, entry, actor, path) });
    }
    return options;
  }

  /**
   * Whether a group's entries describe one tracked resource (value / max...) rather than things to roll
   * @param {Array<{key: string}>} options
   * @returns {boolean}
   */
  static #isResource(options) {
    const keys = options.map(option => option.key.toLowerCase());
    return keys.includes("max") && keys.some(key => RESOURCE_KEYS.includes(key) && key !== "max");
  }

  /**
   * Numeric value of an entry: the entry itself, or its value / total / mod property
   * @param {*} entry
   * @returns {number|null}
   */
  static #numericValue(entry) {
    if (typeof entry === "number" && Number.isFinite(entry)) return entry;
    if (!entry || typeof entry !== "object") return null;
    for (const field of ["value", "total", "mod"]) {
      if (typeof entry[field] === "number" && Number.isFinite(entry[field])) return entry[field];
    }
    return null;
  }

  /**
   * Label of a group entry
   * @param {string} key
   * @param {*} entry
   * @returns {string}
   */
  static #entryLabel(key, entry, actor, path) {
    const own = entry && typeof entry === "object" ? (entry.label ?? entry.name) : null;
    if (typeof own === "string" && own.trim()) return game.i18n.localize(own);
    const field = path ? this.#schemaField(actor, `${path}.${key}`) : null;
    const fieldLabel = field?.hint || field?.label;
    if (typeof fieldLabel === "string" && fieldLabel.trim()) return game.i18n.localize(fieldLabel);
    return this.humanize(key);
  }

  /**
   * Data model field at a path of the actor's system data, used for labels declared in the schema
   * @param {Actor} actor
   * @param {string} path
   * @returns {foundry.data.fields.DataField|null}
   */
  static #schemaField(actor, path) {
    try {
      return actor?.system?.schema?.getField?.(path) ?? null;
    } catch (error) {
      return null;
    }
  }

  /**
   * Own enumerable entries of plain data or a data model
   * @param {*} data
   * @returns {Array<[string, *]>}
   */
  static #entries(data) {
    if (!this.#isWalkable(data)) return [];
    return Object.entries(data).filter(([key]) => !key.startsWith("_"));
  }

  /**
   * Whether a value is an object worth walking: not an array, document, collection or set
   * @param {*} value
   * @returns {boolean}
   */
  static #isWalkable(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) return false;
    if (value instanceof foundry.abstract.Document || value instanceof Map || value instanceof Set) return false;
    return true;
  }

  /**
   * Unsaved actor of a type, used to read the type's default data and methods
   * @param {string} type
   * @returns {Actor|null}
   */
  static #standIn(type) {
    try {
      return new Actor.implementation({ name: type, type });
    } catch (error) {
      LogUtil.warn("SystemRollDiscovery - could not build a stand-in actor", [type, error]);
      return null;
    }
  }
}
