import { LogUtil } from "../utils/LogUtil.mjs";

/**
 * Sequencer database path or file path used for teleport effects. Empty means "auto detect JB2A".
 * @type {string}
 */
export const DEFAULT_TELEPORT_ANIMATION_PATH = "";

/**
 * Optional departure / arrival effects for teleports, played through Sequencer with JB2A assets
 * when both modules are active. Everything here is a no-op when they are missing.
 * @module tokens/TokenTeleportAnimations
 */
export class TokenTeleportAnimations {
  static #jb2aFile = "Library/Generic/Energy/Teleport/Teleport01_01_Regular_Blue_500x300.webm";
  static #sequencerPaths = [
    "jb2a.teleportation.circle.blue",
    "jb2a.teleport.circle.blue",
    "jb2a.teleportation.blue"
  ];

  /**
   * Whether an animation can be played at all
   * @returns {boolean}
   */
  static isAvailable() {
    return !!(DEFAULT_TELEPORT_ANIMATION_PATH || this.hasJB2A()) && this.hasSequencer();
  }

  /**
   * Whether Sequencer is active
   * @returns {boolean}
   */
  static hasSequencer() {
    return !!game.modules.get("sequencer")?.active;
  }

  /**
   * The active JB2A module, if any
   * @returns {Module|undefined}
   */
  static getJB2AModule() {
    return game.modules.get("JB2A_DnD5e") || game.modules.get("jb2a_patreon");
  }

  /**
   * Whether a JB2A module is active
   * @returns {boolean}
   */
  static hasJB2A() {
    return !!this.getJB2AModule()?.active;
  }

  /**
   * Directory prefix configured for JB2A assets
   * @param {Module} jb2aModule
   * @returns {string}
   */
  static getJB2APrefix(jb2aModule) {
    try {
      const location = game.settings.get(jb2aModule.id, "jb2aLocation");
      if (location && location !== "modules") {
        return location.replace(/\/+$/, "");
      }
    } catch (error) {
      LogUtil.log("TokenTeleportAnimations: jb2aLocation setting unavailable");
    }
    return "modules";
  }

  /**
   * Resolve the effect path to play
   * @returns {string|null}
   */
  static getAnimationPath() {
    if (DEFAULT_TELEPORT_ANIMATION_PATH) return DEFAULT_TELEPORT_ANIMATION_PATH;
    if (this.hasSequencer() && globalThis.Sequencer?.Database) {
      for (const dbPath of this.#sequencerPaths) {
        if (Sequencer.Database.entryExists(dbPath)) return dbPath;
      }
    }
    const jb2aModule = this.getJB2AModule();
    if (jb2aModule?.active) {
      return `${this.getJB2APrefix(jb2aModule)}/${jb2aModule.id}/${this.#jb2aFile}`;
    }
    LogUtil.log("TokenTeleportAnimations: no teleport animation available");
    return null;
  }

  /**
   * Play the effect at the positions tokens leave from
   * @param {Array<{x: number, y: number}>} centers
   * @returns {Promise<void>}
   */
  static playDeparture(centers) {
    return this.#playAt(centers, 400);
  }

  /**
   * Play the effect at the positions tokens arrive at
   * @param {Array<{x: number, y: number}>} centers
   * @returns {Promise<void>}
   */
  static playArrival(centers) {
    return this.#playAt(centers, 250);
  }

  /**
   * Play the effect at every position for every user, then wait for it to become visible
   * @param {Array<{x: number, y: number}>} centers
   * @param {number} waitMs
   * @returns {Promise<void>}
   */
  static async #playAt(centers, waitMs) {
    if (!this.isAvailable()) return;
    const animationPath = this.getAnimationPath();
    if (!animationPath) return;
    const userIds = game.users.map(user => user.id);
    for (const center of centers) {
      new Sequence()
        .effect()
        .file(animationPath)
        .atLocation({ x: center.x, y: center.y })
        .scale(0.5)
        .fadeIn(50)
        .fadeOut(100)
        .forUsers(userIds)
        .play();
    }
    await new Promise(resolve => setTimeout(resolve, waitMs));
  }
}
