import { LogUtil } from "../../utils/LogUtil.mjs";

/**
 * @typedef {Object} SystemProfile
 * @property {string} system - Game system id the profile serves (game.system.id)
 * @property {string} [title] - Display name
 * @property {{minimum?: string, maximum?: string, verified?: string}} [systemVersions] - System versions the profile works with
 * @property {string} [notes] - Remarks for maintainers and GMs
 * @property {import("./SystemConfigStore.mjs").ConfiguredRollType[]} rollTypes
 */

/**
 * Bundled and module-registered system profiles: declarative roll setups in the System Config format, used
 * for systems without a code adapter when the GM has not saved their own setup. See docs/system-profiles.md.
 * @module adapters/configured/SystemProfiles
 */
export class SystemProfiles {
  /** @type {Map<string, SystemProfile>} */
  static #profiles = new Map();

  /**
   * Register a profile, replacing any earlier one for the same system
   * @param {SystemProfile} profile
   * @returns {boolean} Whether the profile was accepted
   */
  static register(profile) {
    if (!profile?.system || !Array.isArray(profile.rollTypes)) {
      LogUtil.warn("SystemProfiles.register - a profile needs a system id and rollTypes", [profile]);
      return false;
    }
    this.#profiles.set(profile.system, profile);
    return true;
  }

  /**
   * Profile registered for a system id, regardless of version
   * @param {string} systemId
   * @returns {SystemProfile|null}
   */
  static get(systemId) {
    return this.#profiles.get(systemId) ?? null;
  }

  /**
   * Profile for the running system when its version is inside the profile's range
   * @returns {SystemProfile|null}
   */
  static forActiveSystem() {
    const profile = this.get(game.system?.id);
    if (!profile) return null;
    if (!this.supportsVersion(profile, game.system.version)) {
      LogUtil.warn("SystemProfiles - the profile does not cover this system version", [profile.system, game.system.version, profile.systemVersions]);
      return null;
    }
    return profile;
  }

  /**
   * Whether a system version is inside the profile's minimum / maximum range
   * @param {SystemProfile} profile
   * @param {string} version
   * @returns {boolean}
   */
  static supportsVersion(profile, version) {
    const { minimum, maximum } = profile.systemVersions ?? {};
    if (!version) return true;
    if (minimum && foundry.utils.isNewerVersion(minimum, version)) return false;
    if (maximum && foundry.utils.isNewerVersion(version, maximum) && !String(version).startsWith(`${maximum}.`)) return false;
    return true;
  }

  /**
   * Every registered profile
   * @returns {SystemProfile[]}
   */
  static list() {
    return Array.from(this.#profiles.values());
  }
}
