import { MODULE_ID } from "../constants/General.mjs";
import { HOOKS_MODULE } from "../constants/Hooks.mjs";
import { getSettings, SETTING_SCOPE } from "../constants/Settings.mjs";
import { getDefaultIconLayout } from "../constants/IconMappings.mjs";
import { LogUtil } from "./LogUtil.mjs";
import { GeneralUtil } from "./GeneralUtil.mjs";

/**
 * Registers and reads module settings. Side effects of a changed setting are broadcast through
 * the `flash-token-bar.settingChanged` hook so features subscribe without importing this file.
 * @module utils/SettingsUtil
 */
export class SettingsUtil {
  /** @type {string} */
  static coreColorScheme = "dark";

  /**
   * Tags of the world settings a non-GM user may override for themselves
   * @type {Set<string>}
   */
  static #overridable = new Set();

  /**
   * Register every setting defined in constants/Settings.mjs
   */
  static registerAll() {
    const SETTINGS = getSettings();
    for (const setting of Object.values(SETTINGS)) {
      if (setting.userOverridable) SettingsUtil.#overridable.add(setting.tag);
      const config = {
        name: setting.label,
        hint: setting.hint,
        default: setting.default,
        type: setting.propType,
        scope: setting.scope,
        config: setting.config,
        requiresReload: setting.requiresReload || false,
        restricted: setting.scope === SETTING_SCOPE.world,
        onChange: value => SettingsUtil.apply(setting.tag, value)
      };
      if (setting.choices) {
        config.choices = setting.choices;
      }
      if (setting.range) {
        config.range = setting.range;
      }
      try {
        game.settings.register(MODULE_ID, setting.tag, config);
      } catch (error) {
        LogUtil.log(`Setting ${setting.tag} already registered`, [error]);
      }
    }
  }

  /**
   * Read the Foundry interface colour scheme
   */
  static updateColorScheme() {
    const uiConfig = game.settings.get("core", "uiConfig");
    let interfaceTheme = uiConfig?.colorScheme?.interface;
    if (!interfaceTheme) {
      interfaceTheme = matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark";
    }
    SettingsUtil.coreColorScheme = interfaceTheme;
  }

  /**
   * Get a setting value
   * @param {string} settingName - Setting tag
   * @param {string} [moduleName=MODULE_ID]
   * @returns {*}
   */
  static get(settingName, moduleName = MODULE_ID) {
    if (!settingName) return null;
    try {
      if (moduleName === MODULE_ID && SettingsUtil.hasUserOverride(settingName)) {
        return SettingsUtil.userOverrides()[settingName];
      }
      return game.settings.get(moduleName, settingName);
    } catch (error) {
      LogUtil.log(`Setting ${moduleName}.${settingName} not registered`);
      return undefined;
    }
  }

  /**
   * Set a setting value
   * @param {string} settingName - Setting tag
   * @param {*} newValue
   * @param {string} [moduleName=MODULE_ID]
   * @returns {Promise<boolean>}
   */
  static async set(settingName, newValue, moduleName = MODULE_ID) {
    if (!settingName) return false;
    try {
      if (moduleName === MODULE_ID && SettingsUtil.isUserOverridable(settingName)) {
        await SettingsUtil.setUserOverride(settingName, newValue);
        return true;
      }
      await game.settings.set(moduleName, settingName, newValue);
      return true;
    } catch (error) {
      LogUtil.error("SettingsUtil.set failed", [settingName, error]);
      return false;
    }
  }

  /**
   * Whether the current user keeps their own value for a world setting instead of the GM's default
   * @param {string} settingName
   * @returns {boolean}
   */
  static isUserOverridable(settingName) {
    return !game.user?.isGM && SettingsUtil.#overridable.has(settingName);
  }

  /**
   * Whether the current user has stored their own value for the setting
   * @param {string} settingName
   * @returns {boolean}
   */
  static hasUserOverride(settingName) {
    return SettingsUtil.isUserOverridable(settingName) && settingName in SettingsUtil.userOverrides();
  }

  /**
   * The current user's stored overrides
   * @returns {Object<string, *>}
   */
  static userOverrides() {
    const SETTINGS = getSettings();
    try {
      return game.settings.get(MODULE_ID, SETTINGS.userOverrides.tag) ?? {};
    } catch (error) {
      return {};
    }
  }

  /**
   * Store the user's own value for a world setting and broadcast the change
   * @param {string} settingName
   * @param {*} newValue
   */
  static async setUserOverride(settingName, newValue) {
    const SETTINGS = getSettings();
    const overrides = { ...SettingsUtil.userOverrides(), [settingName]: newValue };
    await game.settings.set(MODULE_ID, SETTINGS.userOverrides.tag, overrides);
    SettingsUtil.apply(settingName, newValue);
  }

  /**
   * Drop the user's own values so the GM defaults apply again
   * @param {string[]} settingNames
   */
  static async clearUserOverrides(settingNames) {
    const SETTINGS = getSettings();
    const overrides = { ...SettingsUtil.userOverrides() };
    const cleared = settingNames.filter(name => name in overrides);
    for (const name of cleared) delete overrides[name];
    await game.settings.set(MODULE_ID, SETTINGS.userOverrides.tag, overrides);
    for (const name of cleared) SettingsUtil.apply(name, SettingsUtil.get(name));
  }

  /**
   * Broadcast a changed setting so features can react
   * @param {string} settingName
   * @param {*} newValue
   */
  static apply(settingName, newValue) {
    const SETTINGS = getSettings();
    if (settingName === SETTINGS.maxIconsPerRow.tag) {
      SettingsUtil.applyMaxIconsPerRow(newValue);
    }
    Hooks.callAll(HOOKS_MODULE.SETTING_CHANGED, settingName, newValue);
  }

  /**
   * Publish the icon limit as a CSS variable
   */
  static initializeMaxIconsPerRow() {
    const SETTINGS = getSettings();
    const maxIconsPerRow = SettingsUtil.get(SETTINGS.maxIconsPerRow.tag) || 5;
    GeneralUtil.addCSSVars("--ftb-menu-icons-limit", maxIconsPerRow);
  }

  /**
   * Update the icon limit CSS variable
   * @param {number} newValue
   */
  static applyMaxIconsPerRow(newValue) {
    const SETTINGS = getSettings();
    let maxIconsPerRow = newValue || SettingsUtil.get(SETTINGS.maxIconsPerRow.tag) || 5;
    if (maxIconsPerRow < 1) maxIconsPerRow = 1;
    GeneralUtil.addCSSVars("--ftb-menu-icons-limit", maxIconsPerRow);
  }

  /**
   * Add icons introduced by newer versions to a stored layout and drop icons that no longer exist
   */
  static async validateAndUpdateIconLayout() {
    const SETTINGS = getSettings();
    const currentLayout = SettingsUtil.get(SETTINGS.menuIconsLayout.tag);
    const defaultLayout = getDefaultIconLayout();
    if (!currentLayout) {
      return;
    }

    let updated = false;
    const updatedLayout = foundry.utils.deepClone(currentLayout);

    for (const [iconType, defaultIcons] of Object.entries(defaultLayout)) {
      updatedLayout[iconType] ??= [];
      const validIds = new Set(defaultIcons.map(icon => icon.id));
      const before = updatedLayout[iconType].length;
      updatedLayout[iconType] = updatedLayout[iconType].filter(icon => validIds.has(icon.id));
      if (updatedLayout[iconType].length !== before) {
        updated = true;
      }
      const existingIds = new Set(updatedLayout[iconType].map(icon => icon.id));
      let maxOrder = Math.max(-1, ...updatedLayout[iconType].map(icon => icon.order || 0));
      for (const defaultIcon of defaultIcons) {
        if (existingIds.has(defaultIcon.id)) continue;
        maxOrder++;
        updatedLayout[iconType].push({ ...defaultIcon, order: maxOrder });
        updated = true;
      }
    }

    if (updated && game.user.isGM) {
      await SettingsUtil.set(SETTINGS.menuIconsLayout.tag, updatedLayout);
    }
  }
}
