import { SystemRollDiscovery } from "./SystemRollDiscovery.mjs";
import { RollCallBuilder } from "./RollCallBuilder.mjs";
import { LogUtil } from "../../utils/LogUtil.mjs";

const MESSAGE_WAIT_MS = 1500;

/**
 * @typedef {Object} RollOutcome
 * @property {Roll|null} roll - The Roll behind the result, when one was found
 * @property {*} returned - What the system function returned
 */

/**
 * Rolls section built from a System Config or a bundled system profile. A roll type with a formula rolls that
 * formula; otherwise it calls the chosen actor, system data, sheet, item or API function, with arguments from
 * the roll type's template or filled by parameter name, and reads the result from what the function returns
 * or from the chat message it posts for the actor.
 * @module adapters/configured/ConfiguredRolls
 */
export class ConfiguredRolls {
  /**
   * Rolls section for the adapter, or null when no roll type is enabled
   * @param {import("./SystemConfigStore.mjs").SystemConfig|null} config
   * @returns {import("../../core/Capabilities.mjs").RollsSection|null}
   */
  static section(config) {
    const rollTypes = (config?.rollTypes ?? []).filter(rollType => rollType.enabled);
    if (rollTypes.length === 0) return null;
    return {
      icon: "fas fa-dice",
      totalIsSuccessCount: rollTypes.every(rollType => rollType.result?.successCount === true),
      getRollTypes: actors => this.getRollTypes(rollTypes, actors),
      roll: (actor, type, options) => this.roll(rollTypes, actor, type, options),
      getValue: (actor, type, key) => this.getValue(rollTypes, actor, type, key)
    };
  }

  /**
   * Roll types for the Rolls tab, with options from the roll type's fixed list or read from the given actors
   * @param {import("./SystemConfigStore.mjs").ConfiguredRollType[]} rollTypes
   * @param {Actor[]} actors
   * @returns {import("../../core/Capabilities.mjs").RollTypeDef[]}
   */
  static getRollTypes(rollTypes, actors = []) {
    const sources = actors.length > 0 ? actors : Array.from(SystemRollDiscovery.sampleActors().values()).slice(0, 1);
    return rollTypes.map(rollType => {
      if (Array.isArray(rollType.options) && rollType.options.length > 0) {
        const options = rollType.options.map(option => ({ key: option.key, label: game.i18n.localize(option.label ?? option.key) }));
        return { type: rollType.id, label: game.i18n.localize(rollType.label), nested: true, options };
      }
      if (!rollType.group) return { type: rollType.id, label: game.i18n.localize(rollType.label) };
      const options = new Map();
      for (const actor of sources) {
        for (const option of SystemRollDiscovery.optionsOf(actor, rollType.group)) {
          if (!options.has(option.key)) options.set(option.key, option);
        }
      }
      return { type: rollType.id, label: game.i18n.localize(rollType.label), nested: true, options: Array.from(options.values()) };
    }).filter(def => !def.nested || def.options.length > 0);
  }

  /**
   * Value of a roll option on an actor
   * @param {import("./SystemConfigStore.mjs").ConfiguredRollType[]} rollTypes
   * @param {Actor} actor
   * @param {string} type
   * @param {string} key
   * @returns {number}
   */
  static getValue(rollTypes, actor, type, key) {
    const rollType = rollTypes.find(entry => entry.id === type);
    if (!rollType?.group || !key) return 0;
    return SystemRollDiscovery.readValue(actor, rollType.group, key) ?? 0;
  }

  /**
   * Roll a configured roll type for an actor
   * @param {import("./SystemConfigStore.mjs").ConfiguredRollType[]} rollTypes
   * @param {Actor} actor
   * @param {string} type
   * @param {Object} options
   * @returns {Promise<import("../../core/Capabilities.mjs").AdapterRollResult>}
   */
  static async roll(rollTypes, actor, type, options = {}) {
    const rollType = rollTypes.find(entry => entry.id === type);
    if (!rollType) return { error: true, message: `Unknown roll type "${type}"` };
    try {
      const context = this.#context(rollType, actor, options);
      const outcome = rollType.formula?.trim()
        ? await this.#rollFormula(rollType, context, options)
        : await this.#rollMethod(rollType, context);
      const result = this.#readResult(rollType, outcome, context.dc);
      if (!result) return { cancelled: true };
      await this.#afterRoll(rollType, outcome.returned);
      return result;
    } catch (error) {
      LogUtil.error("ConfiguredRolls.roll", [error, actor, type, options]);
      return { error: true, message: error.message ?? "Roll failed" };
    }
  }

  /**
   * Everything a call or formula can use about this roll
   * @param {import("./SystemConfigStore.mjs").ConfiguredRollType} rollType
   * @param {Actor} actor
   * @param {Object} options
   * @returns {import("./RollCallBuilder.mjs").RollCallContext}
   */
  static #context(rollType, actor, options) {
    const key = rollType.group || rollType.options?.length ? (options.key ?? undefined) : undefined;
    const group = rollType.group ?? "";
    const optionLabel = key ? this.#optionLabel(rollType, actor, key) : null;
    const secondKey = rollType.secondKey;
    const key2 = secondKey && key ? SystemRollDiscovery.readSecondKey(actor, group, key, secondKey.from) : null;
    return {
      actor,
      label: optionLabel ? `${game.i18n.localize(rollType.label)}: ${optionLabel}` : game.i18n.localize(rollType.label),
      group,
      key,
      value: key && group ? SystemRollDiscovery.readValue(actor, group, key) : null,
      key2: key2 ?? undefined,
      value2: key2 && secondKey?.group ? SystemRollDiscovery.readValue(actor, secondKey.group, key2) : null,
      item: key && SystemRollDiscovery.isItemGroup(group) ? SystemRollDiscovery.itemFor(actor, group, key) : null,
      dc: options.dc ? Number(options.dc) : null,
      rollMode: options.rollMode,
      fastForward: options.fastForward ?? false
    };
  }

  /**
   * Display label of the chosen option
   * @param {import("./SystemConfigStore.mjs").ConfiguredRollType} rollType
   * @param {Actor} actor
   * @param {string} key
   * @returns {string|null}
   */
  static #optionLabel(rollType, actor, key) {
    const fixed = rollType.options?.find(option => option.key === key);
    if (fixed) return game.i18n.localize(fixed.label ?? fixed.key);
    return SystemRollDiscovery.optionsOf(actor, rollType.group).find(option => option.key === key)?.label ?? null;
  }

  /**
   * Roll the formula; {value}, {value2}, {key}... are filled from the roll, @paths read the actor's roll data
   * @param {import("./SystemConfigStore.mjs").ConfiguredRollType} rollType
   * @param {import("./RollCallBuilder.mjs").RollCallContext} context
   * @param {Object} options
   * @returns {Promise<RollOutcome>}
   */
  static async #rollFormula(rollType, context, options) {
    const formula = RollCallBuilder.fill([rollType.formula], { ...context, value: context.value ?? 0, value2: context.value2 ?? 0 })[0];
    const roll = new Roll(formula, context.actor.getRollData?.() ?? {});
    await roll.evaluate();
    await roll.toMessage({ speaker: ChatMessage.getSpeaker({ actor: context.actor }), flavor: context.label }, { rollMode: options.rollMode });
    return { roll, returned: roll };
  }

  /**
   * Call the system function and find the Roll it made
   * @param {import("./SystemConfigStore.mjs").ConfiguredRollType} rollType
   * @param {import("./RollCallBuilder.mjs").RollCallContext} context
   * @returns {Promise<RollOutcome>}
   */
  static async #rollMethod(rollType, context) {
    const { actor } = context;
    const resolved = SystemRollDiscovery.resolveMethod(rollType.method, actor, { group: context.group, key: context.key });
    if (!resolved) throw new Error(`${rollType.method} is not available for ${actor.name}`);
    const args = Array.isArray(rollType.args) ? RollCallBuilder.fill(rollType.args, context) : RollCallBuilder.buildArgs(resolved.fn, context);
    const capture = this.#captureRollMessage(actor);
    try {
      const returned = await resolved.fn.apply(resolved.thisArg, args);
      const needsRoll = (rollType.result?.from ?? "roll") === "roll";
      const roll = this.#rollFrom(returned) ?? (needsRoll || returned === undefined ? await capture.wait(MESSAGE_WAIT_MS) : null);
      return { roll, returned };
    } finally {
      capture.stop();
    }
  }

  /**
   * Result in the core's shape, read as the roll type describes: from the Roll (default) or from the value the
   * function returned, with the total and pass/fail at the given paths. Without a pass path, the total is
   * compared with the target (at least, or at most for roll-under systems).
   * @param {import("./SystemConfigStore.mjs").ConfiguredRollType} rollType
   * @param {RollOutcome} outcome
   * @param {number|null} dc
   * @returns {import("../../core/Capabilities.mjs").AdapterRollResult|null}
   */
  static #readResult(rollType, outcome, dc) {
    const spec = rollType.result ?? {};
    const source = spec.from === "return" ? outcome.returned : outcome.roll;
    if (source === undefined || source === null) return null;
    const total = Number(foundry.utils.getProperty(source, spec.total ?? "total"));
    if (!Number.isFinite(total)) return null;
    let passed = null;
    if (spec.passed) {
      const value = foundry.utils.getProperty(source, spec.passed);
      if (value !== undefined && value !== null) passed = !!value;
    } else if (dc !== null && dc !== undefined) {
      passed = spec.compare === "atMost" ? total <= dc : total >= dc;
    }
    return {
      roll: outcome.roll ?? undefined,
      total,
      formula: outcome.roll?.formula ?? "",
      success: passed === null ? null : { passed, properties: [] }
    };
  }

  /**
   * Run the follow-up the system expects after a roll, e.g. Daggerheart's resourceUpdates.updateResources()
   * @param {import("./SystemConfigStore.mjs").ConfiguredRollType} rollType
   * @param {*} returned
   * @returns {Promise<void>}
   */
  static async #afterRoll(rollType, returned) {
    if (!rollType.afterRoll || !returned || typeof returned !== "object") return;
    const parentPath = rollType.afterRoll.split(".").slice(0, -1).join(".");
    const fn = foundry.utils.getProperty(returned, rollType.afterRoll);
    if (typeof fn !== "function") return;
    try {
      await fn.call(parentPath ? foundry.utils.getProperty(returned, parentPath) : returned);
    } catch (error) {
      LogUtil.error("ConfiguredRolls.afterRoll", [error, rollType.afterRoll]);
    }
  }

  /**
   * Find a Roll in whatever a system function returned: a Roll, an array, a chat message or an object holding one
   * @param {*} result
   * @returns {Roll|null}
   */
  static #rollFrom(result) {
    if (!result) return null;
    if (result instanceof Roll) return result;
    if (Array.isArray(result)) return result.map(entry => this.#rollFrom(entry)).find(Boolean) ?? null;
    if (result instanceof ChatMessage) return result.rolls?.[0] ?? null;
    if (typeof result === "object") {
      return this.#rollFrom(result.roll) ?? this.#rollFrom(result.rolls) ?? this.#rollFrom(result.message) ?? null;
    }
    return null;
  }

  /**
   * Listen for the next chat message with rolls spoken by the actor
   * @param {Actor} actor
   * @returns {{wait: function(number): Promise<Roll|null>, stop: function(): void}}
   */
  static #captureRollMessage(actor) {
    let captured = null;
    let notify = null;
    const hookId = Hooks.on("createChatMessage", message => {
      if (captured || !message.rolls?.length) return;
      if (message.speaker?.actor !== actor.id && message.speaker?.token !== actor.token?.id) return;
      captured = message.rolls[0];
      notify?.(captured);
    });
    return {
      wait: ms => captured ? Promise.resolve(captured) : new Promise(resolve => {
        notify = resolve;
        setTimeout(() => resolve(captured), ms);
      }),
      stop: () => Hooks.off("createChatMessage", hookId)
    };
  }
}
