import { LogUtil } from "../utils/LogUtil.mjs";
import { HOOKS_MODULE } from "../constants/Hooks.mjs";
import { SystemAdapter } from "../adapters/SystemAdapter.mjs";
import { GenericAdapter } from "../adapters/generic/GenericAdapter.mjs";
import { SystemConfigStore } from "../adapters/configured/SystemConfigStore.mjs";
import { ConfiguredRolls } from "../adapters/configured/ConfiguredRolls.mjs";
import { SystemProfiles } from "../adapters/configured/SystemProfiles.mjs";

/**
 * Holds every registered SystemAdapter and resolves the one matching the running game system.
 * Built-in adapters register during init; external modules register on the
 * `flash-token-bar.registerAdapters` hook or by calling the module API before `setup` ends.
 * @module core/AdapterRegistry
 */
export class AdapterRegistry {
  /** @type {Map<string, SystemAdapter>} */
  static #adapters = new Map();

  /** @type {SystemAdapter|null} */
  static #active = null;

  /**
   * Register an adapter. Accepts a SystemAdapter instance, a subclass, or a plain object with the adapter shape.
   * Registering for a system id that already has an adapter replaces the previous one.
   * @param {SystemAdapter|Function|Object} adapterLike
   * @returns {SystemAdapter} The stored adapter
   */
  static register(adapterLike) {
    const adapter = SystemAdapter.from(adapterLike);
    if (!adapter.id) {
      throw new Error("Flash Token Bar | An adapter must declare the system id it serves");
    }
    this.#adapters.set(adapter.id, adapter);
    LogUtil.log("AdapterRegistry.register", [adapter.id, adapter.capabilities]);
    if (this.#active && this.#active.id === adapter.id) {
      this.resolve();
    }
    return adapter;
  }

  /**
   * Remove an adapter by system id
   * @param {string} systemId
   */
  static unregister(systemId) {
    this.#adapters.delete(systemId);
  }

  /**
   * Get a registered adapter by system id
   * @param {string} systemId
   * @returns {SystemAdapter|undefined}
   */
  static get(systemId) {
    return this.#adapters.get(systemId);
  }

  /**
   * All registered adapters
   * @returns {SystemAdapter[]}
   */
  static list() {
    return Array.from(this.#adapters.values());
  }

  /**
   * Pick the adapter for the running system, falling back to the generic adapter.
   * @returns {SystemAdapter}
   */
  static resolve() {
    const systemId = game.system?.id;
    const adapter = this.#adapters.get(systemId) ?? new GenericAdapter(systemId);
    this.#active = adapter;
    this.applySystemConfig();
    LogUtil.log("AdapterRegistry.resolve", [systemId, adapter.name, adapter.capabilities]);
    Hooks.callAll(HOOKS_MODULE.ADAPTER_READY, adapter);
    return adapter;
  }

  /**
   * Whether a module or built-in adapter serves the running system, in which case the GM's System Config is not used
   * @returns {boolean}
   */
  static hasRegisteredAdapter() {
    return this.#adapters.has(game.system?.id);
  }

  /**
   * Give the generic adapter its rolls: the GM's System Config when saved, otherwise the bundled profile for the
   * system. Called on resolve and when the config changes.
   */
  static applySystemConfig() {
    if (!this.#active || this.hasRegisteredAdapter()) return;
    this.#active.rolls = ConfiguredRolls.section(SystemConfigStore.get() ?? SystemProfiles.forActiveSystem());
  }

  /**
   * The adapter serving the current game system
   * @returns {SystemAdapter}
   */
  static get active() {
    if (!this.#active) {
      this.resolve();
    }
    return this.#active;
  }

  /**
   * Whether the active adapter provides a capability
   * @param {string} capability - One of CAPABILITIES
   * @returns {boolean}
   */
  static hasCapability(capability) {
    return this.active.capabilities.includes(capability);
  }
}
