import { TokenTeleportAnimations } from "./TokenTeleportAnimations.mjs";

/**
 * @typedef {Object} TeleportTokenData
 * @property {string} id - Token document id
 * @property {string} sceneId - Scene the token started in
 * @property {number} x
 * @property {number} y
 * @property {number} width - Width in grid units
 * @property {number} height - Height in grid units
 * @property {string} src - Texture path
 * @property {Object} documentData - Full token document source
 */

/**
 * @typedef {Object} TeleportPlacement
 * @property {TeleportTokenData} tokenData
 * @property {string} src
 * @property {number} x - Top left in target scene pixels
 * @property {number} y
 * @property {number} width - Pixel width in the target scene
 * @property {number} height
 * @property {number} centerX
 * @property {number} centerY
 */

/**
 * Geometry and document updates for a teleport: keeps the group layout around a destination
 * center, moves tokens within a scene or recreates them in another one, with optional effects.
 * @module tokens/TokenTeleportExecutor
 */
export class TokenTeleportExecutor {
  /**
   * Group bounding box in source scene pixels
   * @param {TeleportTokenData[]} tokenData
   * @param {number} gridSize
   * @returns {{x: number, y: number, width: number, height: number}}
   */
  static boundingBox(tokenData, gridSize) {
    if (tokenData.length === 0) return { x: 0, y: 0, width: 0, height: 0 };
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const data of tokenData) {
      minX = Math.min(minX, data.x);
      minY = Math.min(minY, data.y);
      maxX = Math.max(maxX, data.x + data.width * gridSize);
      maxY = Math.max(maxY, data.y + data.height * gridSize);
    }
    return { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
  }

  /**
   * Token centers in the source scene
   * @param {TeleportTokenData[]} tokenData
   * @param {Scene} sourceScene
   * @returns {Array<{x: number, y: number}>}
   */
  static departureCenters(tokenData, sourceScene) {
    const gridSize = sourceScene.grid.size;
    return tokenData.map(data => ({
      x: data.x + data.width * gridSize / 2,
      y: data.y + data.height * gridSize / 2
    }));
  }

  /**
   * Destination placements keeping the group layout around a center point
   * @param {TeleportTokenData[]} tokenData
   * @param {Scene} sourceScene
   * @param {{x: number, y: number}} center - Group center in target scene pixels
   * @param {Scene} targetScene
   * @param {boolean} snap - Snap each token center to the target grid
   * @returns {TeleportPlacement[]}
   */
  static computePlacements(tokenData, sourceScene, center, targetScene, snap) {
    const sourceGrid = sourceScene.grid.size;
    const targetGrid = targetScene.grid.size;
    const box = this.boundingBox(tokenData, sourceGrid);
    const groupCenterX = box.x + box.width / 2;
    const groupCenterY = box.y + box.height / 2;
    return tokenData.map(data => {
      const width = data.width * targetGrid;
      const height = data.height * targetGrid;
      const relativeX = (data.x + data.width * sourceGrid / 2 - groupCenterX) / sourceGrid;
      const relativeY = (data.y + data.height * sourceGrid / 2 - groupCenterY) / sourceGrid;
      let centerX = center.x + relativeX * targetGrid;
      let centerY = center.y + relativeY * targetGrid;
      if (snap) {
        const snapped = targetScene.grid.getSnappedPoint({ x: centerX, y: centerY }, { mode: CONST.GRID_SNAPPING_MODES.CENTER });
        centerX = snapped.x;
        centerY = snapped.y;
      }
      return { tokenData: data, src: data.src, x: centerX - width / 2, y: centerY - height / 2, width, height, centerX, centerY };
    });
  }

  /**
   * Move (same scene) or recreate (other scene) the tokens around the destination
   * @param {TeleportTokenData[]} tokenData - Tokens that still exist in the source scene
   * @param {Scene} sourceScene
   * @param {Scene} targetScene
   * @param {{x: number, y: number}} destination - Group center in target scene pixels
   * @returns {Promise<string[]>} Ids of the teleported tokens in the target scene
   */
  static async execute(tokenData, sourceScene, targetScene, destination) {
    const ids = tokenData.map(data => data.id);
    const placements = this.computePlacements(tokenData, sourceScene, destination, targetScene, true);
    const arrivals = placements.map(p => ({ x: p.centerX, y: p.centerY }));

    await sourceScene.updateEmbeddedDocuments("Token", ids.map(_id => ({ _id, alpha: 0.3 })), { animate: false });
    await TokenTeleportAnimations.playDeparture(this.departureCenters(tokenData, sourceScene));

    let teleportedIds;
    if (sourceScene.id === targetScene.id) {
      const constrainOptions = { ignoreWalls: true, ignoreCost: true, ignoreTokens: true };
      const movement = Object.fromEntries(ids.map(id => [id, { constrainOptions }]));
      const updates = placements.map(p => ({ _id: p.tokenData.id, x: p.x, y: p.y, alpha: 0.3 }));
      await sourceScene.updateEmbeddedDocuments("Token", updates, { animate: false, movement });
      teleportedIds = ids;
    } else {
      await sourceScene.deleteEmbeddedDocuments("Token", ids);
      const createData = placements.map(p => ({ ...foundry.utils.deepClone(p.tokenData.documentData), x: p.x, y: p.y, alpha: 0.3 }));
      const created = await targetScene.createEmbeddedDocuments("Token", createData);
      teleportedIds = created.map(token => token.id);
    }

    await TokenTeleportAnimations.playArrival(arrivals);
    await targetScene.updateEmbeddedDocuments("Token", teleportedIds.map(_id => ({ _id, alpha: 1 })), { animate: false });
    return teleportedIds;
  }

  /**
   * Select the teleported tokens on the canvas and pan to their center
   * @param {string[]} tokenIds
   * @returns {Promise<void>}
   */
  static async focus(tokenIds) {
    if (tokenIds.length === 0) return;
    await new Promise(resolve => setTimeout(resolve, 50));
    const tokens = tokenIds.map(id => canvas.tokens.get(id)).filter(token => !!token);
    if (tokens.length === 0) return;
    canvas.tokens.releaseAll();
    tokens.forEach(token => token.control({ releaseOthers: false }));
    const x = tokens.reduce((sum, token) => sum + token.center.x, 0) / tokens.length;
    const y = tokens.reduce((sum, token) => sum + token.center.y, 0) / tokens.length;
    await canvas.animatePan({ x, y, duration: 150 });
  }
}
